-- Manually attested payments settle recorded net liabilities,not new wages.
INSERT INTO public.capability_catalog(name,label,workspace,sensitive,scope_kinds) VALUES
 ('payrun-payments.view','View private payroll payments and recorded settlement balances','Finance',true,ARRAY['hub','person','country','region','city']),
 ('payrun-payments.edit','Request reviewed payroll payment records and exact corrections','Finance',true,ARRAY['hub','person','country','region','city']);
CREATE TABLE public.payrun_payments(
 academy_id uuid NOT NULL,id uuid NOT NULL,posting_id uuid NOT NULL,input jsonb NOT NULL,plan jsonb NOT NULL,amount_minor numeric NOT NULL CHECK(amount_minor>0 AND amount_minor=trunc(amount_minor) AND amount_minor<1e38),posted_on date NOT NULL,reference text NOT NULL,reversal_id uuid,
 funding_account uuid NOT NULL,funding_version integer NOT NULL,method_id uuid NOT NULL,method_version integer NOT NULL,evidence_file uuid,evidence_version integer,handled_by uuid,
 approval_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),PRIMARY KEY(academy_id,id),FOREIGN KEY(academy_id,posting_id) REFERENCES public.payrun_net_postings(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id)
);
ALTER TABLE public.payrun_payments ADD FOREIGN KEY(academy_id,funding_account,funding_version) REFERENCES public.finance_account_revisions(academy_id,account_id,version),ADD FOREIGN KEY(academy_id,method_id,method_version) REFERENCES public.finance_payment_method_revisions(academy_id,method_id,version),ADD FOREIGN KEY(academy_id,evidence_file,evidence_version) REFERENCES public.file_record_revisions(academy_id,file_id,version),ADD FOREIGN KEY(academy_id,handled_by) REFERENCES public.people(academy_id,id),ADD CHECK((evidence_file IS NULL)=(evidence_version IS NULL));
CREATE UNIQUE INDEX payrun_payment_reference ON public.payrun_payments(academy_id,posting_id,reference) WHERE reference<>'' AND reversal_id IS NULL;
CREATE INDEX payrun_payment_posting ON public.payrun_payments(academy_id,posting_id,posted_on,id);
CREATE TABLE public.payrun_payment_reversals(
 academy_id uuid NOT NULL,id uuid NOT NULL,payment_id uuid NOT NULL,input jsonb NOT NULL,source_snapshot jsonb NOT NULL,posted_on date NOT NULL,approval_id uuid NOT NULL,created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
 PRIMARY KEY(academy_id,id),UNIQUE(academy_id,payment_id),UNIQUE(academy_id,id,payment_id),FOREIGN KEY(academy_id,payment_id) REFERENCES public.payrun_payments(academy_id,id),FOREIGN KEY(academy_id,id) REFERENCES public.finance_journals(academy_id,id) DEFERRABLE INITIALLY DEFERRED,FOREIGN KEY(academy_id,approval_id) REFERENCES public.approval_requests(academy_id,id),FOREIGN KEY(academy_id,created_by) REFERENCES public.people(academy_id,id)
);
ALTER TABLE public.payrun_payments ADD CONSTRAINT payrun_payment_reversal_identity FOREIGN KEY(academy_id,reversal_id,id) REFERENCES public.payrun_payment_reversals(academy_id,id,payment_id) DEFERRABLE INITIALLY DEFERRED;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['payrun_payments','payrun_payment_reversals'] LOOP
 EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE public.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_boundary ON public.%I USING(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid) WITH CHECK(academy_id=nullif(current_setting(''app.academy_id'',true),'''')::uuid)',t);EXECUTE format('GRANT SELECT ON public.%I TO kavosh_runtime',t);EXECUTE format('CREATE TRIGGER payrun_payment_write BEFORE INSERT OR UPDATE OR DELETE ON public.%I FOR EACH STATEMENT EXECUTE FUNCTION public.guard_expense_commitment_write()',t);
END LOOP;END $$;
CREATE VIEW public.payrun_payment_events WITH(security_invoker=true) AS
 SELECT p.academy_id,p.posting_id,p.id payment_id,p.posted_on,(a->>'accountId')::uuid account_id,(a->>'minor')::numeric paid_minor FROM public.payrun_payments p CROSS JOIN LATERAL jsonb_array_elements(p.plan->'allocations') a
 UNION ALL SELECT p.academy_id,p.posting_id,p.id,v.posted_on,(a->>'accountId')::uuid,-(a->>'minor')::numeric FROM public.payrun_payment_reversals v JOIN public.payrun_payments p ON p.academy_id=v.academy_id AND p.id=v.payment_id CROSS JOIN LATERAL jsonb_array_elements(p.plan->'allocations') a;
GRANT SELECT ON public.payrun_payment_events TO kavosh_runtime;
CREATE FUNCTION public.payrun_payment_balances(p_posting uuid,p_on date,p_exclude uuid DEFAULT NULL) RETURNS TABLE(account_id uuid,budget_minor numeric,paid_minor numeric,balance_minor numeric,capacity_minor numeric) LANGUAGE sql VOLATILE SET search_path=pg_catalog AS $$
 WITH posting AS(SELECT * FROM public.payrun_net_postings WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_posting),
 origins AS(SELECT(o->>'accountId')::uuid id,sum((o->>'minor')::numeric) gross FROM posting p CROSS JOIN LATERAL jsonb_array_elements(p.plan->'origins') o GROUP BY o->>'accountId'),
 withheld AS(SELECT(w->>'accountId')::uuid id,(w->>'minor')::numeric minor FROM posting p CROSS JOIN LATERAL jsonb_array_elements(p.plan->'wageDeductions') w),
 budgets AS(SELECT o.id,CASE WHEN p_on IS NULL OR p_on>=(SELECT(input->>'postedOn')::date FROM posting) THEN o.gross-coalesce(w.minor,0) ELSE 0 END budget FROM origins o LEFT JOIN withheld w ON w.id=o.id),
 daily AS(SELECT account_id id,posted_on,sum(paid_minor) delta FROM public.payrun_payment_events WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND posting_id=p_posting AND payment_id IS DISTINCT FROM p_exclude GROUP BY account_id,posted_on),
 totals AS(SELECT b.id,b.budget,coalesce(sum(d.delta) FILTER(WHERE p_on IS NULL OR d.posted_on<=p_on),0) paid FROM budgets b LEFT JOIN daily d ON d.id=b.id GROUP BY b.id,b.budget),
 running AS(SELECT id,posted_on,sum(delta) OVER(PARTITION BY id ORDER BY posted_on ROWS UNBOUNDED PRECEDING) paid FROM daily),
 peaks AS(SELECT b.id,greatest(0,coalesce((SELECT max(paid) FROM running r WHERE r.id=b.id AND(p_on IS NULL OR r.posted_on>=p_on)),0),coalesce((SELECT sum(delta) FROM daily d WHERE d.id=b.id AND(p_on IS NULL OR d.posted_on<=p_on)),0),coalesce((SELECT sum(delta) FROM daily d WHERE d.id=b.id),0)) paid FROM budgets b)
 SELECT t.id,t.budget,t.paid,t.budget-t.paid,greatest(0,t.budget-k.paid) FROM totals t JOIN peaks k ON k.id=t.id ORDER BY t.id
$$;
CREATE FUNCTION public.payrun_payment_input_valid(i jsonb) RETURNS boolean LANGUAGE plpgsql IMMUTABLE SET search_path=pg_catalog AS $$ DECLARE keys text[];k text;v jsonb;d date;stamp timestamptz;BEGIN
 keys=ARRAY['amount','fundingAccount','method','period','postedOn','paidAt','reference','evidence','missingEvidenceReason','handledById','operationalReview','taxTreatment','reason'];
 IF jsonb_typeof(i) IS DISTINCT FROM 'object' OR NOT(i ?& keys) OR i-keys<>'{}'::jsonb OR octet_length(i::text)>65536 OR i->>'taxTreatment' IS DISTINCT FROM 'settle_recorded_net_pay' OR jsonb_typeof(i->'amount') IS DISTINCT FROM 'string' OR length(i->>'amount')>80 OR i->>'amount'!~'^[0-9]+([.][0-9]+)?$' THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['reference','missingEvidenceReason','operationalReview','reason','paidAt','postedOn'] LOOP IF jsonb_typeof(i->k) IS DISTINCT FROM 'string' OR length(i->>k)>2000 THEN RETURN false;END IF;END LOOP;
 IF length(i->>'reference')>200 OR length(btrim(i->>'operationalReview'))=0 OR length(btrim(i->>'reason'))=0 OR i->>'postedOn'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR length(i->>'paidAt')>40 OR i->>'paidAt'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}(:[0-9]{2}([.][0-9]{1,6})?)?(Z|[+-][0-9]{2}:[0-9]{2})$' THEN RETURN false;END IF;
 d=(i->>'postedOn')::date;stamp=(i->>'paidAt')::timestamptz;IF d NOT BETWEEN DATE '1900-01-01' AND DATE '9999-12-31' OR stamp<TIMESTAMPTZ '1900-01-01T00:00:00Z' THEN RETURN false;END IF;
 FOREACH k IN ARRAY ARRAY['fundingAccount','method','period','evidence'] LOOP v=i->k;IF k='evidence' AND v='null'::jsonb THEN CONTINUE;END IF;
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR NOT(v ?& ARRAY['id','version']) OR v-ARRAY['id','version']<>'{}'::jsonb OR jsonb_typeof(v->'id') IS DISTINCT FROM 'string' OR v->>'id'!~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' OR jsonb_typeof(v->'version') IS DISTINCT FROM 'number' OR(v->>'version')::numeric NOT BETWEEN 1 AND 2147483647 OR(v->>'version')::numeric<>trunc((v->>'version')::numeric) THEN RETURN false;END IF;
 END LOOP;
 RETURN(i->'evidence'<>'null'::jsonb OR length(btrim(i->>'missingEvidenceReason'))>0) AND(i->'handledById'='null'::jsonb OR(jsonb_typeof(i->'handledById')='string' AND i->>'handledById'~'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'));
 EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range THEN RETURN false;
END $$;
CREATE FUNCTION public.payrun_payment_reverse_source(p_payment uuid,i jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;r record;s jsonb;accounts jsonb;period jsonb;closed date;BEGIN
 SELECT * INTO p FROM public.payrun_payments WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_payment;IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO r FROM public.payrun_net_postings WHERE academy_id=p.academy_id AND id=p.posting_id;s=public.payrun_net_source(r.run_id);
 SELECT * INTO p FROM public.payrun_payments WHERE academy_id=p.academy_id AND id=p_payment;
 SELECT max(ends_on) INTO closed FROM public.finance_periods WHERE academy_id=p.academy_id AND active_closing_run_id IS NOT NULL AND state='closed';
 SELECT jsonb_build_object('id',id,'version',version,'state',state,'startsOn',starts_on::text,'endsOn',ends_on::text,'closedThrough',closed::text) INTO period FROM public.finance_periods WHERE academy_id=p.academy_id AND id=(i#>>'{period,id}')::uuid;
 SELECT jsonb_agg(jsonb_build_object('id',a.id,'hubId',a.hub_id,'version',a.version,'active',a.active,'kind',a.kind,'unitScale',a.unit_scale) ORDER BY a.id) INTO accounts FROM public.finance_account_catalogue a WHERE a.academy_id=p.academy_id AND a.id IN(SELECT(x->>'id')::uuid FROM jsonb_array_elements(p.plan->'accounts') x);
 RETURN jsonb_build_object('source',s,'postingId',r.id,'paymentId',p.id,'reversalId',p.reversal_id,'postedOn',p.posted_on::text,'planSha256',encode(sha256(convert_to(p.plan::text,'UTF8')),'hex'),'accounts',accounts,'period',period,'method',p.plan->'method','evidence',p.plan->'evidence','handler',p.plan->'handler');
END $$;
CREATE FUNCTION public.guard_payrun_payment() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE p record;b jsonb;s jsonb;r record;BEGIN
 IF TG_OP='DELETE' THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_HISTORY_IMMUTABLE' USING ERRCODE='23514';END IF;
 IF TG_OP='UPDATE' THEN
  IF TG_TABLE_NAME<>'payrun_payments' OR(to_jsonb(NEW)-'reversal_id') IS DISTINCT FROM(to_jsonb(OLD)-'reversal_id') OR OLD.reversal_id IS NOT NULL OR NEW.reversal_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.payrun_payment_reversals v WHERE v.academy_id=NEW.academy_id AND v.id=NEW.reversal_id AND v.payment_id=NEW.id) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EXACT_REVERSAL_REQUIRED' USING ERRCODE='23514';END IF;RETURN NEW;
 END IF;
 SELECT * INTO p FROM public.approval_requests WHERE academy_id=NEW.academy_id AND id=NEW.approval_id;
 IF TG_TABLE_NAME='payrun_payments' THEN
  b=public.payrun_payment_plan(NEW.posting_id,NEW.input,NEW.id);s=b->'source';
  IF b IS NULL OR b->>'unavailable' IS NOT NULL OR NEW.plan IS DISTINCT FROM b OR NEW.reversal_id IS NOT NULL OR p.action IS DISTINCT FROM 'work.payrun-payment.record' OR p.payload IS DISTINCT FROM(jsonb_build_object('postingId',NEW.posting_id)||NEW.input) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EXACT_SOURCE_REQUIRED' USING ERRCODE='23514';END IF;
  NEW.amount_minor=(b->>'amountMinor')::numeric;NEW.posted_on=(NEW.input->>'postedOn')::date;NEW.reference=NEW.input->>'reference';NEW.funding_account=(NEW.input#>>'{fundingAccount,id}')::uuid;NEW.funding_version=(NEW.input#>>'{fundingAccount,version}')::integer;NEW.method_id=(NEW.input#>>'{method,id}')::uuid;NEW.method_version=(NEW.input#>>'{method,version}')::integer;NEW.evidence_file=(NEW.input#>>'{evidence,id}')::uuid;NEW.evidence_version=(NEW.input#>>'{evidence,version}')::integer;NEW.handled_by=(NEW.input->>'handledById')::uuid;
 ELSE
  SELECT * INTO r FROM public.payrun_payments WHERE academy_id=NEW.academy_id AND id=NEW.payment_id;b=public.payrun_payment_reverse_source(NEW.payment_id,NEW.input);s=b->'source';
  IF b IS NULL OR r.reversal_id IS NOT NULL OR NEW.input->>'paymentId' IS DISTINCT FROM NEW.payment_id::text OR NEW.input-ARRAY['paymentId','period','postedOn','reason']<>'{}'::jsonb OR NOT(NEW.input ?& ARRAY['paymentId','period','postedOn','reason']) OR jsonb_typeof(NEW.input->'reason') IS DISTINCT FROM 'string' OR length(btrim(NEW.input->>'reason')) NOT BETWEEN 1 AND 2000 OR p.action IS DISTINCT FROM 'work.payrun-payment.reverse' OR p.payload IS DISTINCT FROM NEW.input OR NEW.source_snapshot IS DISTINCT FROM b OR b#>>'{period,state}' IS DISTINCT FROM 'open' OR(b#>>'{period,version}')::integer IS DISTINCT FROM(NEW.input#>>'{period,version}')::integer OR(NEW.input->>'postedOn')::date NOT BETWEEN(b#>>'{period,startsOn}')::date AND(b#>>'{period,endsOn}')::date OR(NEW.input->>'postedOn')::date<r.posted_on OR(b#>>'{period,closedThrough}' IS NOT NULL AND(NEW.input->>'postedOn')::date<=(b#>>'{period,closedThrough}')::date) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_REVERSAL_SOURCE_INVALID' USING ERRCODE='23514';END IF;
  NEW.posted_on=(NEW.input->>'postedOn')::date;
 END IF;
 IF p.id IS NULL OR p.status<>'pending' OR p.target_id IS DISTINCT FROM NEW.id OR p.target_version IS DISTINCT FROM 0 OR p.privacy_capability IS DISTINCT FROM 'payrun-payments.view' OR p.scope IS DISTINCT FROM s->'scope' OR p.review_context IS DISTINCT FROM b OR NOT public.report_comment_human_verified(NEW.created_by) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EXACT_REVIEW_REQUIRED' USING ERRCODE='23514';END IF;
 IF(NEW.created_by::text=s->>'personId' OR NEW.created_by::text=b#>>'{handler,id}') AND NOT EXISTS(SELECT 1 FROM public.academies WHERE id=NEW.academy_id AND master_person_id=NEW.created_by) THEN RAISE EXCEPTION 'BENEFICIARY_REVIEW_FORBIDDEN' USING ERRCODE='23514';END IF;
 NEW.created_at=clock_timestamp();RETURN NEW;
END $$;
CREATE TRIGGER payrun_payment_guard BEFORE INSERT OR UPDATE OR DELETE ON public.payrun_payments FOR EACH ROW EXECUTE FUNCTION public.guard_payrun_payment();
CREATE TRIGGER payrun_payment_reversal_guard BEFORE INSERT OR UPDATE OR DELETE ON public.payrun_payment_reversals FOR EACH ROW EXECUTE FUNCTION public.guard_payrun_payment();
GRANT INSERT(academy_id,id,posting_id,input,plan,approval_id,created_by),UPDATE(reversal_id) ON public.payrun_payments TO kavosh_runtime;
GRANT INSERT(academy_id,id,payment_id,input,source_snapshot,approval_id,created_by) ON public.payrun_payment_reversals TO kavosh_runtime;
CREATE FUNCTION public.payrun_payment_complete() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE r record;j record;lines jsonb;reversing boolean;parent uuid;BEGIN
 reversing=TG_TABLE_NAME='payrun_payment_reversals';
 IF reversing THEN SELECT * INTO r FROM public.payrun_payments WHERE academy_id=NEW.academy_id AND id=NEW.payment_id;lines=r.plan->'lines';parent=r.id;IF r.reversal_id IS DISTINCT FROM NEW.id OR jsonb_set(public.payrun_payment_reverse_source(NEW.payment_id,NEW.input),'{reversalId}','null'::jsonb) IS DISTINCT FROM NEW.source_snapshot THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_REVERSAL_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;
 ELSE lines=NEW.plan->'lines';parent=NULL;IF public.payrun_payment_plan(NEW.posting_id,NEW.input,NEW.id) IS DISTINCT FROM NEW.plan THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_SOURCE_CHANGED' USING ERRCODE='23514';END IF;END IF;
 SELECT * INTO j FROM public.finance_journals WHERE academy_id=NEW.academy_id AND id=NEW.id;
 IF j.id IS NULL OR j.approval_id IS DISTINCT FROM NEW.approval_id OR j.posted_by IS DISTINCT FROM NEW.created_by OR j.period_id IS DISTINCT FROM(NEW.input#>>'{period,id}')::uuid OR j.period_version IS DISTINCT FROM(NEW.input#>>'{period,version}')::integer OR j.posted_on IS DISTINCT FROM NEW.posted_on OR j.purpose IS DISTINCT FROM 'activity' OR j.reverses_id IS DISTINCT FROM parent OR j.line_count<>jsonb_array_length(lines) OR j.description IS DISTINCT FROM(CASE WHEN reversing THEN 'Correction of recorded payroll payment' ELSE 'Recorded payroll payment' END) OR j.reference IS DISTINCT FROM(CASE WHEN reversing THEN 'PAYRUN-PAYMENT-REVERSAL' ELSE 'PAYRUN-PAYMENT' END) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EXACT_JOURNAL_REQUIRED' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(lines) WITH ORDINALITY x(v,n) LEFT JOIN public.finance_journal_lines a ON a.academy_id=NEW.academy_id AND a.journal_id=NEW.id AND a.line_number=x.n WHERE a.account_id IS DISTINCT FROM(x.v->>'accountId')::uuid OR a.account_version IS DISTINCT FROM(x.v->>'accountVersion')::integer OR a.amount_minor IS DISTINCT FROM(x.v->>'amountMinor')::numeric OR a.side IS DISTINCT FROM(CASE WHEN reversing THEN CASE WHEN x.v->>'side'='debit' THEN 'credit' ELSE 'debit' END ELSE x.v->>'side' END) OR a.note IS DISTINCT FROM '') THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EXACT_LINES_REQUIRED' USING ERRCODE='23514';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.audit_events a WHERE a.academy_id=NEW.academy_id AND a.entity_id=NEW.id AND a.actor_id=NEW.created_by AND a.created_at=transaction_timestamp() AND a.action=CASE WHEN reversing THEN 'work.payrun-payment.reverse' ELSE 'work.payrun-payment.record' END AND a.changes->>'approvalId'=NEW.approval_id::text AND a.changes->'moneyMovementPerformed'='false'::jsonb) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_AUDIT_RECEIPT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER payrun_payment_complete AFTER INSERT ON public.payrun_payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.payrun_payment_complete();
CREATE CONSTRAINT TRIGGER payrun_payment_reversal_complete AFTER INSERT ON public.payrun_payment_reversals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.payrun_payment_complete();
CREATE CONSTRAINT TRIGGER payrun_payment_reviewed AFTER INSERT ON public.payrun_payments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE CONSTRAINT TRIGGER payrun_payment_reversal_reviewed AFTER INSERT ON public.payrun_payment_reversals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.reviewed_approval_complete();
CREATE FUNCTION public.payrun_payment_effect_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.status='applied' AND((NEW.action='work.payrun-payment.record' AND NOT EXISTS(SELECT 1 FROM public.payrun_payments WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id)) OR(NEW.action='work.payrun-payment.reverse' AND NOT EXISTS(SELECT 1 FROM public.payrun_payment_reversals WHERE academy_id=NEW.academy_id AND id=NEW.target_id AND approval_id=NEW.id AND created_by=NEW.reviewer_id))) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_EFFECT_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER payrun_payment_effect_required AFTER INSERT OR UPDATE ON public.approval_requests DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.payrun_payment_effect_required();
CREATE FUNCTION public.payrun_payment_posting_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE person uuid;last_date date;BEGIN
 SELECT g.person_id INTO person FROM public.payrun_net_postings p JOIN public.payrun_groups g ON g.academy_id=p.academy_id AND g.id=p.run_id WHERE p.academy_id=NEW.academy_id AND p.id=NEW.posting_id;PERFORM public.lock_hourly_worker(person);
 IF EXISTS(SELECT 1 FROM public.payrun_payments WHERE academy_id=NEW.academy_id AND posting_id=NEW.posting_id AND reversal_id IS NULL) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_REVERSALS_REQUIRED' USING ERRCODE='23514';END IF;
 SELECT max(e.posted_on) INTO last_date FROM public.payrun_payment_events e WHERE e.academy_id=NEW.academy_id AND e.posting_id=NEW.posting_id;IF last_date IS NOT NULL AND(NEW.input->>'postedOn')::date<last_date THEN RAISE EXCEPTION 'PAYRUN_POSTING_REVERSAL_PRECEDES_PAYMENT_HISTORY' USING ERRCODE='23514';END IF;RETURN NEW;
END $$;
CREATE TRIGGER payrun_payment_posting_guard BEFORE INSERT ON public.payrun_net_posting_reversals FOR EACH ROW EXECUTE FUNCTION public.payrun_payment_posting_guard();
CREATE FUNCTION public.payrun_payment_privacy() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ DECLARE cap text;ctx jsonb:=NEW.review_context;s jsonb;BEGIN
 s=ctx#>'{source,scope}';IF s IS NULL THEN NEW.privacy_bindings=NEW.privacy_bindings||'[{"unresolved":true}]'::jsonb;RETURN NEW;END IF;
 FOREACH cap IN ARRAY ARRAY['payruns.view','payrun-net.view','payrun-postings.view'] LOOP NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'scope',s));END LOOP;
 FOREACH cap IN ARRAY ARRAY['work-pay.view','payroll-accruals.view','payroll-adjustments.view'] LOOP
  IF cap='work-pay.view' OR EXISTS(SELECT 1 FROM public.payrun_groups g CROSS JOIN LATERAL jsonb_array_elements(g.source_snapshot->'items') v WHERE g.academy_id=NEW.academy_id AND g.id=(ctx#>>'{source,runId}')::uuid AND(cap='payroll-adjustments.view')=(v->>'kind'='manual_bonus')) THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'payrunNetSource',ctx#>>'{source,runId}'));END IF;
 END LOOP;
 FOREACH cap IN ARRAY ARRAY['accounts.view','journals.view'] LOOP NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability',cap,'scope',CASE WHEN EXISTS(SELECT 1 FROM jsonb_array_elements(ctx->'accounts') a WHERE a->'hubId'='null'::jsonb) THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',(SELECT jsonb_agg(DISTINCT a->'hubId') FROM jsonb_array_elements(ctx->'accounts') a)) END));END LOOP;
 NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','payment-methods.view','scope',CASE WHEN ctx#>'{method,hubId}'='null'::jsonb THEN '{"all":true,"hubs":[]}'::jsonb ELSE jsonb_build_object('all',false,'hubs',jsonb_build_array(ctx#>'{method,hubId}')) END));
 IF ctx->'evidence'<>'null'::jsonb THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('fileId',ctx#>>'{evidence,id}'));END IF;
 IF ctx->'handler'<>'null'::jsonb THEN NEW.privacy_bindings=NEW.privacy_bindings||jsonb_build_array(jsonb_build_object('capability','people.view','personId',ctx#>>'{handler,id}'));END IF;RETURN NEW;
END $$;
CREATE TRIGGER zz_payrun_payment_privacy BEFORE INSERT ON public.approval_requests FOR EACH ROW WHEN(NEW.action IN('work.payrun-payment.record','work.payrun-payment.reverse')) EXECUTE FUNCTION public.payrun_payment_privacy();
CREATE FUNCTION public.payrun_payment_journal_reversal_required() RETURNS trigger LANGUAGE plpgsql SET search_path=pg_catalog AS $$ BEGIN
 IF NEW.reverses_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.payrun_payments p WHERE p.academy_id=NEW.academy_id AND p.id=NEW.reverses_id) AND NOT EXISTS(SELECT 1 FROM public.payrun_payment_reversals r JOIN public.payrun_payments p ON p.academy_id=r.academy_id AND p.id=r.payment_id WHERE r.academy_id=NEW.academy_id AND r.id=NEW.id AND p.id=NEW.reverses_id AND p.reversal_id=r.id) THEN RAISE EXCEPTION 'PAYRUN_PAYMENT_NATIVE_REVERSAL_WORKFLOW_REQUIRED' USING ERRCODE='23514';END IF;RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER payrun_payment_journal_reversal AFTER INSERT ON public.finance_journals DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.payrun_payment_journal_reversal_required();
REVOKE ALL ON FUNCTION public.payrun_payment_balances(uuid,date,uuid),public.payrun_payment_input_valid(jsonb),public.payrun_payment_reverse_source(uuid,jsonb),public.guard_payrun_payment(),public.payrun_payment_complete(),public.payrun_payment_effect_required(),public.payrun_payment_posting_guard(),public.payrun_payment_privacy(),public.payrun_payment_journal_reversal_required() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.payrun_payment_balances(uuid,date,uuid),public.payrun_payment_input_valid(jsonb),public.payrun_payment_reverse_source(uuid,jsonb) TO kavosh_runtime;
CREATE FUNCTION public.payrun_payment_plan(p_posting uuid,i jsonb,p_exclude uuid DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
DECLARE p record;s jsonb;accounts jsonb;fund record;m record;period jsonb;closed date;caps jsonb;allocations jsonb;lines jsonb;evidence jsonb;handler jsonb;amount numeric;available numeric;scale integer;activity bigint;bad boolean;BEGIN
 IF NOT public.payrun_payment_input_valid(i) THEN RETURN jsonb_build_object('unavailable','INVALID_PAYRUN_PAYMENT_INPUT');END IF;
 SELECT * INTO p FROM public.payrun_net_postings WHERE academy_id=nullif(current_setting('app.academy_id',true),'')::uuid AND id=p_posting;IF NOT FOUND THEN RETURN NULL;END IF;
 s=public.payrun_net_source(p.run_id);SELECT * INTO p FROM public.payrun_net_postings WHERE academy_id=p.academy_id AND id=p_posting;
 IF p.reversal_id IS NOT NULL OR s->'recordedSourcesCurrent' IS DISTINCT FROM 'true'::jsonb OR s->'cancellationId'<>'null'::jsonb OR s->>'runSourceSha256' IS DISTINCT FROM p.plan#>>'{source,runSourceSha256}' OR(i->>'postedOn')::date<(p.input->>'postedOn')::date THEN RETURN jsonb_build_object('unavailable','ACTIVE_CURRENT_PAYRUN_POSTING_REQUIRED');END IF;
 scale=(s->>'unitScale')::integer;amount=(i->>'amount')::numeric*power(10::numeric,scale);
 IF amount<=0 OR amount<>trunc(amount) OR amount>=1e38 THEN RETURN jsonb_build_object('unavailable','INVALID_PAYRUN_PAYMENT_AMOUNT');END IF;
 IF(i->>'paidAt')::timestamptz>transaction_timestamp() THEN RETURN jsonb_build_object('unavailable','FUTURE_PAYMENT_CANNOT_BE_ATTESTED');END IF;
 SELECT coalesce(sum(capacity_minor),0),coalesce(jsonb_agg(jsonb_build_object('accountId',account_id,'budget',trunc(budget_minor)::text,'paid',trunc(paid_minor)::text,'balance',trunc(balance_minor)::text,'capacity',trunc(capacity_minor)::text) ORDER BY account_id),'[]'::jsonb) INTO available,caps FROM public.payrun_payment_balances(p.id,(i->>'postedOn')::date,p_exclude);
 IF amount>available THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_EXCEEDS_CURRENT_OR_DATED_BALANCE');END IF;
 SELECT * INTO fund FROM public.finance_account_catalogue WHERE academy_id=p.academy_id AND id=(i#>>'{fundingAccount,id}')::uuid;
 SELECT * INTO m FROM public.finance_payment_method_catalogue WHERE academy_id=p.academy_id AND id=(i#>>'{method,id}')::uuid;
 IF fund.id IS NULL OR NOT fund.active OR fund.version<>(i#>>'{fundingAccount,version}')::integer OR fund.currency_id::text IS DISTINCT FROM s->>'currencyId' OR fund.operational_role NOT IN('cash','bank','credit_card') THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_FUNDING_MAPPING_INVALID');END IF;
 IF m.id IS NULL OR NOT m.active OR m.version<>(i#>>'{method,version}')::integer OR(m.hub_id IS NOT NULL AND m.hub_id IS DISTINCT FROM fund.hub_id AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(s#>'{scope,workContexts}') c WHERE c->>'hubId'=m.hub_id::text)) THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_METHOD_INVALID');END IF;
 SELECT max(ends_on) INTO closed FROM public.finance_periods WHERE academy_id=p.academy_id AND active_closing_run_id IS NOT NULL AND state='closed';
 SELECT jsonb_build_object('id',id,'version',version,'state',state,'startsOn',starts_on::text,'endsOn',ends_on::text,'closedThrough',closed::text) INTO period FROM public.finance_periods WHERE academy_id=p.academy_id AND id=(i#>>'{period,id}')::uuid;
 IF period IS NULL OR period->>'state'<>'open' OR(period->>'version')::integer<>(i#>>'{period,version}')::integer OR(i->>'postedOn')::date NOT BETWEEN(period->>'startsOn')::date AND(period->>'endsOn')::date OR(closed IS NOT NULL AND(i->>'postedOn')::date<=closed) THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_OPEN_PERIOD_REQUIRED');END IF;
 IF i->'evidence'<>'null'::jsonb THEN SELECT jsonb_build_object('id',id,'version',version,'archived',archived,'domain',domain,'anchorKind',anchor_kind,'hubId',hub_id) INTO evidence FROM public.file_records WHERE academy_id=p.academy_id AND id=(i#>>'{evidence,id}')::uuid;
  IF evidence IS NULL OR evidence->'archived'<>'false'::jsonb OR evidence->>'domain'<>'finance_private' OR(evidence->>'version')::integer<>(i#>>'{evidence,version}')::integer OR(evidence->>'anchorKind'<>'academy' AND NOT(evidence->>'anchorKind'='hub' AND(evidence->>'hubId'=fund.hub_id::text OR EXISTS(SELECT 1 FROM jsonb_array_elements(s#>'{scope,workContexts}') c WHERE c->>'hubId'=evidence->>'hubId')))) THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_EVIDENCE_INVALID');END IF;
 END IF;
 IF i->'handledById'<>'null'::jsonb THEN SELECT jsonb_build_object('id',id,'hubId',hub_id,'kind',kind,'status',status) INTO handler FROM public.people WHERE academy_id=p.academy_id AND id=(i->>'handledById')::uuid;IF handler IS NULL OR handler->>'kind'<>'human' OR handler->>'status'<>'active' THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_HANDLER_INVALID');END IF;END IF;
 IF i->>'reference'<>'' AND EXISTS(SELECT 1 FROM public.payrun_payments WHERE academy_id=p.academy_id AND posting_id=p.id AND reference=i->>'reference' AND reversal_id IS NULL AND id IS DISTINCT FROM p_exclude) THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_REFERENCE_EXISTS');END IF;
 WITH weights AS(SELECT (c->>'accountId')::uuid id,(c->>'capacity')::numeric weight FROM jsonb_array_elements(caps) c),shares AS(SELECT *,div(amount*weight,available) base,mod(amount*weight,available) remainder FROM weights),ranked AS(SELECT *,row_number() OVER(ORDER BY remainder DESC,id) rank,sum(base) OVER() base_total FROM shares)
 SELECT coalesce(jsonb_agg(jsonb_build_object('accountId',id,'minor',trunc(base+CASE WHEN rank<=amount-base_total THEN 1 ELSE 0 END)::text) ORDER BY id) FILTER(WHERE base+CASE WHEN rank<=amount-base_total THEN 1 ELSE 0 END>0),'[]'::jsonb) INTO allocations FROM ranked;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'hubId',hub_id,'version',version,'active',active,'kind',kind,'operationalRole',operational_role,'currencyId',currency_id,'unitScale',unit_scale) ORDER BY id),'[]'::jsonb) INTO accounts FROM public.finance_account_catalogue WHERE academy_id=p.academy_id AND(id=fund.id OR id IN(SELECT(a->>'accountId')::uuid FROM jsonb_array_elements(allocations) a));
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(accounts) a WHERE a->'active'<>'true'::jsonb OR a->>'currencyId' IS DISTINCT FROM s->>'currencyId' OR(a->>'id'<>fund.id::text AND(a->>'kind'<>'liability' OR a->>'operationalRole'<>'payable'))) THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_WAGE_MAPPING_INVALID');END IF;
 WITH amounts AS(SELECT 'WAGE:'||(a->>'accountId') key,(a->>'accountId')::uuid account_id,'debit'::text side,(a->>'minor')::numeric minor FROM jsonb_array_elements(allocations) a UNION ALL SELECT 'FUNDING',fund.id,'credit',amount),scaled AS(SELECT x.*,a.version,a.unit_scale,CASE WHEN a.unit_scale>=scale THEN minor*power(10::numeric,a.unit_scale-scale) ELSE div(minor,power(10::numeric,scale-a.unit_scale)) END local_minor,CASE WHEN a.unit_scale<scale THEN mod(minor,power(10::numeric,scale-a.unit_scale))<>0 ELSE false END precision_lost FROM amounts x JOIN public.finance_account_catalogue a ON a.academy_id=p.academy_id AND a.id=x.account_id)
 SELECT jsonb_agg(jsonb_build_object('accountId',account_id,'accountVersion',version,'side',side,'amountMinor',trunc(local_minor)::text,'unitScale',unit_scale) ORDER BY key),coalesce(bool_or(precision_lost OR local_minor>=1e38),false) INTO lines,bad FROM scaled;
 IF bad THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_ACCOUNT_PRECISION_OR_LINE_LIMIT');END IF;IF jsonb_array_length(lines)>200 THEN RETURN jsonb_build_object('unavailable','PAYRUN_PAYMENT_REQUIRES_BACKGROUND_JOB');END IF;
 SELECT(SELECT count(*) FROM public.payrun_payments WHERE academy_id=p.academy_id AND posting_id=p.id AND id IS DISTINCT FROM p_exclude)+(SELECT count(*) FROM public.payrun_payment_reversals v JOIN public.payrun_payments q ON q.academy_id=v.academy_id AND q.id=v.payment_id WHERE q.academy_id=p.academy_id AND q.posting_id=p.id AND q.id IS DISTINCT FROM p_exclude) INTO activity;
 RETURN jsonb_build_object('source',s,'postingId',p.id,'netVersion',p.net_version,'postingPlanSha256',encode(sha256(convert_to(p.plan::text,'UTF8')),'hex'),'amountMinor',trunc(amount)::text,'balances',caps,'activity',activity,'allocations',allocations,'accounts',accounts,'period',period,'method',jsonb_build_object('id',m.id,'version',m.version,'hubId',m.hub_id,'category',m.category,'active',m.active),'evidence',evidence,'handler',handler,'lines',lines,'unavailable',NULL);
END $$;
REVOKE ALL ON FUNCTION public.payrun_payment_plan(uuid,jsonb,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.payrun_payment_plan(uuid,jsonb,uuid) TO kavosh_runtime;
DO $$ DECLARE body text;needle text:='''period'',period);';BEGIN
 SELECT pg_get_functiondef('public.payrun_posting_reverse_source(uuid,jsonb)'::regprocedure) INTO body;
 IF position(needle IN body)=0 THEN RAISE EXCEPTION 'PAYRUN_REVERSE_EXTENSION_POINT_MISSING';END IF;
 EXECUTE replace(body,needle,'''period'',period,''paymentState'',jsonb_build_object(''active'',(SELECT count(*) FROM public.payrun_payments WHERE academy_id=r.academy_id AND posting_id=r.id AND reversal_id IS NULL),''latestDate'',(SELECT max(posted_on)::text FROM public.payrun_payment_events WHERE academy_id=r.academy_id AND posting_id=r.id)));');
END $$;
CREATE OR REPLACE FUNCTION public.schema_revision() RETURNS integer LANGUAGE sql IMMUTABLE SET search_path=pg_catalog AS $$ SELECT 151 $$;
